/* ==========================================================================
   HK-PATCH: TAMBAHAN.JS
   Logika tambahan untuk:
   1. Perbaikan penuh audio & pemutaran video (Hero & Footer/CTA) agar saat
      suara diaktifkan (unmute) video tidak pernah berhenti dan suara langsung keluar,
      termasuk pada server lokal tanpa dukungan HTTP Range (python -m http.server).
   2. Pop-up Kuis Edukasi 15 Soal (#hkQuizDialog) yang dibuka dari tombol di
      area Anatomi Pohon (#btnOpenQuizModal & #btnOpenQuizFromDetail), dengan
      seluruh 15 soal bersumber dari materi website HutanKita.
   3. Dua Desain Sertifikat & Badge Resmi Berdominasi Putih (1400x1000 px)
      lengkap dengan tanda tangan asli Wahyu Hidayat (Founder HutanKita):
      - Sertifikat & Badge Ikrar Pelestarian Hutan (#hkPledgeCanvas)
      - Sertifikat & Badge Nilai Kelulusan Kuis 15 Soal (#hkQuizCertCanvas)
   ========================================================================== */

const HK_FOUNDER_SIGNATURE_B64 = "data:image/png;base64,";

let hkFounderSigImage = null;
let hkFounderSigLoaded = false;
const hkSigCallbacks = [];

function ensureFounderSignatureLoaded(cb) {
  if (hkFounderSigLoaded && hkFounderSigImage) {
    if (typeof cb === "function") cb(hkFounderSigImage);
    return;
  }
  if (typeof cb === "function") hkSigCallbacks.push(cb);
  if (hkFounderSigImage) return;

  hkFounderSigImage = new Image();
  hkFounderSigImage.onload = () => {
    hkFounderSigLoaded = true;
    while (hkSigCallbacks.length) {
      const fn = hkSigCallbacks.shift();
      try {
        fn(hkFounderSigImage);
      } catch (_e) {
        // ignore
      }
    }
  };
  hkFounderSigImage.onerror = () => {
    if (hkFounderSigImage.src !== "assets/images/ttd-wahyu-hidayat.png") {
      hkFounderSigImage.src = "assets/images/ttd-wahyu-hidayat.png";
    }
  };
  hkFounderSigImage.src = HK_FOUNDER_SIGNATURE_B64;
}

document.addEventListener("DOMContentLoaded", () => {
  ensureFounderSignatureLoaded();
  initHkVideoAudioFix();
  initHkPledgeCardDialog();
  initHkForestQuiz();
});

/**
 * 1. PERBAIKAN AUDIO & PEMUTARAN VIDEO (HERO & FOOTER/CTA)
 * Mengatasi masalah video berhenti dan suara tidak muncul saat unmute
 * pada Chromium / python -m http.server (yang tidak mendukung HTTP 206 Partial Content).
 */
function initHkVideoAudioFix() {
  const heroVideo = document.querySelector(".hero-video");
  const ctaVideo = document.querySelector(".cta-video-player");
  const soundBtn = document.getElementById("soundBtn");
  const soundMutedIcon = document.getElementById("soundMutedIcon");
  const soundActiveIcon = document.getElementById("soundActiveIcon");

  function syncHeroSoundUi(isMuted) {
    if (!soundBtn) return;
    if (soundMutedIcon) soundMutedIcon.classList.toggle("hidden", !isMuted);
    if (soundActiveIcon) soundActiveIcon.classList.toggle("hidden", isMuted);
    soundBtn.title = isMuted ? "Sound Muted" : "Sound Playing";
  }

  /**
   * Mengubah sumber video menjadi Blob URL di memori peramban ketika dijalankan
   * lewat http:// atau https://. Blob URL mendukung byte-range (206 Partial Content)
   * penuh di memori sehingga saat unmute pada detik berapa pun, dekoder audio
   * langsung aktif tanpa membuat video berhenti atau gagal seek.
   */
  function prepareInMemoryBlobVideo(videoEl, srcPath) {
    if (!videoEl || !srcPath) return Promise.resolve(false);
    if (videoEl._hkBlobReady) return Promise.resolve(true);
    if (videoEl._hkBlobPromise) return videoEl._hkBlobPromise;
    if (window.location.protocol !== "http:" && window.location.protocol !== "https:") {
      return Promise.resolve(false);
    }

    videoEl._hkBlobPromise = fetch(srcPath, { cache: "force-cache" })
      .then((res) => {
        if (!res.ok) throw new Error("Fetch video status " + res.status);
        return res.blob();
      })
      .then((blob) => {
        const blobUrl = URL.createObjectURL(
          blob.type ? blob : new Blob([blob], { type: "video/mp4" })
        );
        const savedTime = videoEl.currentTime || 0;
        const savedMuted = videoEl.muted;
        const savedVolume = videoEl.volume > 0 ? videoEl.volume : 1.0;

        videoEl._hkSwappingBlob = true;
        const sources = videoEl.querySelectorAll("source");
        sources.forEach((s) => s.removeAttribute("src"));
        videoEl.src = blobUrl;
        videoEl.muted = savedMuted;
        if (!savedMuted) {
          videoEl.removeAttribute("muted");
        }
        videoEl.volume = savedVolume;
        videoEl.load();

        return new Promise((resolve) => {
          const onLoadedMeta = () => {
            videoEl.removeEventListener("loadedmetadata", onLoadedMeta);
            if (savedTime > 0 && isFinite(savedTime) && savedTime < (videoEl.duration || 9999)) {
              try {
                videoEl.currentTime = savedTime;
              } catch (_e) {
                // ignore
              }
            }
            videoEl.muted = savedMuted;
            videoEl.volume = savedVolume;
            videoEl._hkBlobReady = true;
            videoEl._hkSwappingBlob = false;
            const playPromise = videoEl.play();
            if (playPromise && typeof playPromise.catch === "function") {
              playPromise.catch(() => {});
            }
            resolve(true);
          };
          videoEl.addEventListener("loadedmetadata", onLoadedMeta);
        });
      })
      .catch(() => {
        videoEl._hkSwappingBlob = false;
        return false;
      });

    return videoEl._hkBlobPromise;
  }

  // Pre-buffer ke memori saat ada interaksi pengguna pertama (atau saat tombol suara diklik)
  // agar tidak menggandakan unduhan jaringan pada pemuatan awal (Lighthouse initial load)
  let blobPreloadTriggered = false;
  function triggerVideoBlobPreloadOnce() {
    if (blobPreloadTriggered) return;
    blobPreloadTriggered = true;
    if (ctaVideo) {
      prepareInMemoryBlobVideo(ctaVideo, "assets/videos/footer-video.mp4");
    }
    if (heroVideo) {
      prepareInMemoryBlobVideo(heroVideo, "assets/videos/hero-video.mp4");
    }
  }
  window.addEventListener("pointerdown", triggerVideoBlobPreloadOnce, { once: true, passive: true });
  window.addEventListener("keydown", triggerVideoBlobPreloadOnce, { once: true, passive: true });

  function ensurePlayingWithAudio(videoEl, fallbackSrc) {
    if (!videoEl) return;
    videoEl.volume = 1.0;

    if (!videoEl.muted) {
      videoEl.removeAttribute("muted");
      // Jika dijalankan di http.server dan Blob belum selesai dimuat, tunggu/aktifkan Blob
      if (
        !videoEl._hkBlobReady &&
        (window.location.protocol === "http:" || window.location.protocol === "https:")
      ) {
        prepareInMemoryBlobVideo(videoEl, fallbackSrc).then(() => {
          videoEl.muted = false;
          videoEl.removeAttribute("muted");
          videoEl.volume = 1.0;
          const p = videoEl.play();
          if (p && typeof p.catch === "function") p.catch(() => {});
        });
        return;
      }
    }

    const playPromise = videoEl.play();
    if (playPromise && typeof playPromise.catch === "function") {
      playPromise.catch(() => {
        // Fallback apabila peramban menahan pemutaran
        setTimeout(() => {
          const retry = videoEl.play();
          if (retry && typeof retry.catch === "function") retry.catch(() => {});
        }, 60);
      });
    }
  }

  // Handler tambahan pada tombol suara Hero (#soundBtn)
  if (soundBtn && heroVideo) {
    soundBtn.addEventListener("click", () => {
      // Handler di script.js sudah membalik heroVideo.muted = !heroVideo.muted
      const isNowMuted = heroVideo.muted;
      syncHeroSoundUi(isNowMuted);

      if (!isNowMuted) {
        // Matikan suara video footer agar tidak bertabrakan
        if (ctaVideo && !ctaVideo.muted) {
          ctaVideo.muted = true;
        }
        ensurePlayingWithAudio(heroVideo, "assets/videos/hero-video.mp4");
      } else {
        if (heroVideo.paused) {
          const p = heroVideo.play();
          if (p && typeof p.catch === "function") p.catch(() => {});
        }
      }
    });

    // Jaga agar Hero video tidak pernah berhenti sendiri ketika volume/mute berubah
    heroVideo.addEventListener("volumechange", () => {
      if (heroVideo._hkSwappingBlob) return;
      syncHeroSoundUi(heroVideo.muted);
      if (!heroVideo.muted) {
        heroVideo.removeAttribute("muted");
        if (heroVideo.volume === 0) heroVideo.volume = 1.0;
        if (ctaVideo && !ctaVideo.muted) ctaVideo.muted = true;
      }
      if (heroVideo.paused && !document.hidden) {
        ensurePlayingWithAudio(heroVideo, "assets/videos/hero-video.mp4");
      }
    });

    heroVideo.addEventListener("pause", () => {
      if (heroVideo._hkSwappingBlob || document.hidden) return;
      // Video background hero dirancang selalu berputar (loop)
      setTimeout(() => {
        if (heroVideo.paused && !heroVideo._hkSwappingBlob) {
          const p = heroVideo.play();
          if (p && typeof p.catch === "function") p.catch(() => {});
        }
      }, 40);
    });
  }

  // Handler pada video Footer / CTA (.cta-video-player)
  if (ctaVideo) {
    let lastCtaMuted = ctaVideo.muted;

    ctaVideo.addEventListener("volumechange", () => {
      if (ctaVideo._hkSwappingBlob) return;
      const isNowMuted = ctaVideo.muted || ctaVideo.volume === 0;

      // Jika pengguna baru saja mengaktifkan suara pada video footer/CTA
      if (lastCtaMuted && !isNowMuted) {
        ctaVideo.removeAttribute("muted");
        if (ctaVideo.volume === 0) ctaVideo.volume = 1.0;

        // Bisukan video hero agar suara tidak bertumpuk
        if (heroVideo && !heroVideo.muted) {
          heroVideo.muted = true;
          syncHeroSoundUi(true);
        }

        ensurePlayingWithAudio(ctaVideo, "assets/videos/footer-video.mp4");
      } else if (ctaVideo.paused && !isNowMuted) {
        // Jika mengklik tombol unmute di kontrol native sempat menjeda video, lanjutkan putar
        ensurePlayingWithAudio(ctaVideo, "assets/videos/footer-video.mp4");
      }

      lastCtaMuted = isNowMuted;
    });
  }
}

/**
 * UTILITAS PENGGAMBARAN SERTIFIKAT & BADGE RESMI BERDOMINASI PUTIH (1400 x 1000 px)
 * Digunakan bersama oleh Sertifikat Ikrar (#hkPledgeCanvas) dan Sertifikat Kuis (#hkQuizCertCanvas).
 */
function formatIndonesianDate(dateObj) {
  const months = [
    "Januari",
    "Februari",
    "Maret",
    "April",
    "Mei",
    "Juni",
    "Juli",
    "Agustus",
    "September",
    "Oktober",
    "November",
    "Desember"
  ];
  const d = dateObj.getDate();
  const m = months[dateObj.getMonth()];
  const y = dateObj.getFullYear();
  return `${d} ${m} ${y}`;
}

function wrapCanvasLines(ctx, text, maxWidth) {
  const words = String(text || "").split(/\s+/).filter(Boolean);
  const lines = [];
  let currentLine = "";

  words.forEach((word) => {
    const testLine = currentLine ? `${currentLine} ${word}` : word;
    if (ctx.measureText(testLine).width > maxWidth && currentLine) {
      lines.push(currentLine);
      currentLine = word;
    } else {
      currentLine = testLine;
    }
  });
  if (currentLine) lines.push(currentLine);
  return lines;
}

/**
 * Menggambar bingkai sertifikat putih mewah, ornamen sudut, header brand,
 * segel badge rosette di tengah bawah, dan tanda tangan Founder Wahyu Hidayat.
 */
function drawWhiteCertificateBase(ctx, width, height, config) {
  ctx.save();

  // 1. Latar Belakang Dominan Putih Gading (Warm Ivory-White)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#ffffff");
  bgGrad.addColorStop(0.5, "#fbfdfc");
  bgGrad.addColorStop(1, "#f2f8f5");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Pola gelombang/lingkaran geometris halus di tengah sebagai watermark sertifikat
  ctx.save();
  ctx.strokeStyle = "rgba(16, 185, 129, 0.055)";
  ctx.lineWidth = 1.5;
  for (let r = 140; r <= 440; r += 36) {
    ctx.beginPath();
    ctx.arc(width / 2, height / 2 - 20, r, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();

  // 2. Bingkai Ganda Emerald Tua & Emas Klasik
  const outerPad = 36;
  const innerPad = 52;

  // Pita sudut atas & bawah hijau zamrud gelap
  ctx.fillStyle = "#064e3b";
  ctx.fillRect(outerPad, outerPad, width - outerPad * 2, 12);
  ctx.fillRect(outerPad, height - outerPad - 12, width - outerPad * 2, 12);

  // Garis bingkai luar (Deep Forest Emerald)
  ctx.strokeStyle = "#064e3b";
  ctx.lineWidth = 4;
  ctx.strokeRect(outerPad, outerPad, width - outerPad * 2, height - outerPad * 2);

  // Garis bingkai dalam (Gold-Emerald Accent)
  ctx.strokeStyle = "#b48a3e";
  ctx.lineWidth = 1.8;
  ctx.strokeRect(innerPad, innerPad, width - innerPad * 2, height - innerPad * 2);

  // Ornamen siku di keempat sudut dalam
  const cornerLen = 36;
  const corners = [
    [innerPad + 10, innerPad + 10, 1, 1],
    [width - innerPad - 10, innerPad + 10, -1, 1],
    [innerPad + 10, height - innerPad - 10, 1, -1],
    [width - innerPad - 10, height - innerPad - 10, -1, -1]
  ];
  ctx.strokeStyle = "#059669";
  ctx.lineWidth = 3;
  corners.forEach(([cx, cy, dx, dy]) => {
    ctx.beginPath();
    ctx.moveTo(cx, cy + dy * cornerLen);
    ctx.lineTo(cx, cy);
    ctx.lineTo(cx + dx * cornerLen, cy);
    ctx.stroke();
  });

  // 3. Header Brand & Pill Atas
  const centerX = width / 2;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";

  // Pill kapsul organisasi di bagian atas
  const pillW = 540;
  const pillH = 38;
  const pillX = centerX - pillW / 2;
  const pillY = 92;
  ctx.fillStyle = "#ecfdf5";
  ctx.strokeStyle = "#10b981";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.roundRect ? ctx.roundRect(pillX, pillY, pillW, pillH, 19) : ctx.rect(pillX, pillY, pillW, pillH);
  ctx.fill();
  ctx.stroke();

  ctx.font = "700 15px 'Outfit', sans-serif";
  ctx.fillStyle = "#065f46";
  ctx.fillText(
    config.topPillText || "HUTANKITA INDONESIA  •  PORTAL EDUKASI & KONSERVasi RIMBA",
    centerX,
    pillY + pillH / 2 + 1
  );

  // Judul Utama Sertifikat
  ctx.font = "800 50px 'Outfit', sans-serif";
  ctx.fillStyle = "#052e16";
  ctx.fillText(config.mainTitle || "SERTIFIKAT PENGHARGAAN", centerX, 176);

  // Subjudul Sertifikat
  ctx.font = "600 18px 'Outfit', sans-serif";
  ctx.fillStyle = "#b48a3e";
  ctx.fillText(config.subTitle || "PELESTARIAN EKOSISTEM HUTAN HUJAN TROPIS NUSANTARA", centerX, 220);

  // Garis pemisah dekoratif di bawah subjudul
  ctx.strokeStyle = "rgba(6, 78, 59, 0.22)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(centerX - 240, 246);
  ctx.lineTo(centerX + 240, 246);
  ctx.stroke();

  ctx.fillStyle = "#10b981";
  ctx.beginPath();
  ctx.arc(centerX, 246, 5, 0, Math.PI * 2);
  ctx.fill();

  // 4. Bagian Bawah: Tanggal/Nomor (Kiri), Segel Badge Resmi (Tengah), Tanda Tangan Founder (Kanan)
  const footerBaseY = 790;
  const leftColX = 270;
  const rightColX = width - 270;

  // Kolom Kiri: Tanggal & Nomor Sertifikat
  ctx.textAlign = "center";
  ctx.font = "500 17px 'Outfit', sans-serif";
  ctx.fillStyle = "#475569";
  ctx.fillText("Diterbitkan di Indonesia pada:", leftColX, footerBaseY - 48);

  ctx.font = "700 22px 'Outfit', sans-serif";
  ctx.fillStyle = "#0f172a";
  ctx.fillText(config.dateStr || formatIndonesianDate(new Date()), leftColX, footerBaseY - 14);

  ctx.strokeStyle = "rgba(15, 23, 42, 0.25)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(leftColX - 135, footerBaseY + 12);
  ctx.lineTo(leftColX + 135, footerBaseY + 12);
  ctx.stroke();

  ctx.font = "600 15px 'Outfit', sans-serif";
  ctx.fillStyle = "#047857";
  ctx.fillText(config.serialId || "ID: HK-CERT-2026-8841", leftColX, footerBaseY + 36);

  ctx.font = "400 14px 'Outfit', sans-serif";
  ctx.fillStyle = "#64748b";
  ctx.fillText("Dokumen Digital Terverifikasi HutanKita", leftColX, footerBaseY + 60);

  // Kolom Tengah: Lencana / Segel Badge Resmi (Rosette Emblem)
  drawOfficialSealBadge(
    ctx,
    centerX,
    footerBaseY - 2,
    config.badgeTopText || "OFFICIAL BADGE",
    config.badgeCenterMain || "VERIFIED",
    config.badgeCenterSub || "HUTANKITA"
  );

  // Kolom Kanan: Tanda Tangan Asli Wahyu Hidayat (Founder HutanKita)
  ctx.textAlign = "center";
  ctx.font = "500 17px 'Outfit', sans-serif";
  ctx.fillStyle = "#475569";
  ctx.fillText("Disahkan oleh,", rightColX, footerBaseY - 82);

  // Gambar Tanda Tangan Asli jika sudah siap
  if (hkFounderSigLoaded && hkFounderSigImage) {
    const sigTargetH = 108;
    const sigAspect = (hkFounderSigImage.naturalWidth || 511) / (hkFounderSigImage.naturalHeight || 443);
    const sigTargetW = sigTargetH * sigAspect;
    ctx.drawImage(
      hkFounderSigImage,
      rightColX - sigTargetW / 2,
      footerBaseY - 68,
      sigTargetW,
      sigTargetH
    );
  }

  // Garis tanda tangan
  ctx.strokeStyle = "rgba(15, 23, 42, 0.3)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(rightColX - 140, footerBaseY + 26);
  ctx.lineTo(rightColX + 140, footerBaseY + 26);
  ctx.stroke();

  ctx.font = "800 22px 'Outfit', sans-serif";
  ctx.fillStyle = "#052e16";
  ctx.fillText("Wahyu Hidayat", rightColX, footerBaseY + 52);

  ctx.font = "600 16px 'Outfit', sans-serif";
  ctx.fillStyle = "#047857";
  ctx.fillText("Founder HutanKita", rightColX, footerBaseY + 78);

  ctx.restore();
}

/**
 * Menggambar Lencana / Badge Rosette Emas-Emerald di bagian tengah bawah sertifikat.
 */
function drawOfficialSealBadge(ctx, cx, cy, topLabel, mainLabel, subLabel) {
  ctx.save();

  // Pita bawah kiri & kanan
  ctx.fillStyle = "#065f46";
  ctx.beginPath();
  ctx.moveTo(cx - 28, cy + 52);
  ctx.lineTo(cx - 54, cy + 108);
  ctx.lineTo(cx - 30, cy + 98);
  ctx.lineTo(cx - 14, cy + 114);
  ctx.lineTo(cx - 4, cy + 58);
  ctx.closePath();
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(cx + 28, cy + 52);
  ctx.lineTo(cx + 54, cy + 108);
  ctx.lineTo(cx + 30, cy + 98);
  ctx.lineTo(cx + 14, cy + 114);
  ctx.lineTo(cx + 4, cy + 58);
  ctx.closePath();
  ctx.fill();

  // Gerigi luar rosette (28 titik)
  const points = 28;
  const outerR = 76;
  const innerR = 67;
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 === 0 ? outerR : innerR;
    const angle = (i * Math.PI) / points;
    const x = cx + Math.cos(angle) * r;
    const y = cy + Math.sin(angle) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  const sealGrad = ctx.createLinearGradient(cx - outerR, cy - outerR, cx + outerR, cy + outerR);
  sealGrad.addColorStop(0, "#d4af37");
  sealGrad.addColorStop(0.5, "#f3e5ab");
  sealGrad.addColorStop(1, "#aa7c11");
  ctx.fillStyle = sealGrad;
  ctx.fill();
  ctx.strokeStyle = "#8a620a";
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // Lingkaran dalam hijau zamrud gelap
  ctx.beginPath();
  ctx.arc(cx, cy, 58, 0, Math.PI * 2);
  ctx.fillStyle = "#064e3b";
  ctx.fill();
  ctx.strokeStyle = "#f3e5ab";
  ctx.lineWidth = 2;
  ctx.stroke();

  // Lingkaran garis putus-putus emas di dalam
  ctx.save();
  ctx.beginPath();
  ctx.setLineDash([4, 4]);
  ctx.arc(cx, cy, 50, 0, Math.PI * 2);
  ctx.strokeStyle = "rgba(243, 229, 171, 0.7)";
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.restore();

  // Teks di dalam lencana
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";

  ctx.font = "700 10px 'Outfit', sans-serif";
  ctx.fillStyle = "#f3e5ab";
  ctx.fillText(topLabel, cx, cy - 22);

  ctx.font = "800 18px 'Outfit', sans-serif";
  ctx.fillStyle = "#ffffff";
  ctx.fillText(mainLabel, cx, cy + 1);

  ctx.font = "700 10px 'Outfit', sans-serif";
  ctx.fillStyle = "#6ee7b7";
  ctx.fillText(subLabel, cx, cy + 22);

  ctx.restore();
}

/**
 * 2. SERTIFIKAT & BADGE IKRAR PELESTARIAN HUTAN (<dialog id="hkPledgeDialog"> + <canvas> 1400x1000)
 */
function initHkPledgeCardDialog() {
  const btnPledge = document.getElementById("btnPledgeForest");
  const dialog = document.getElementById("hkPledgeDialog");
  const nameInput = document.getElementById("hkPledgeName");
  const choicesWrap = document.getElementById("hkPledgeChoices");
  const canvas = document.getElementById("hkPledgeCanvas");
  const downloadBtn = document.getElementById("hkPledgeDownloadBtn");
  const closeBtn = document.getElementById("hkPledgeCloseBtn");
  const closeTopBtn = document.getElementById("hkPledgeCloseTopBtn");
  const savedNote = document.getElementById("hkPledgeSavedNote");

  if (!btnPledge || !dialog || !canvas) return;

  const STORAGE_KEY = "hutankita_pledge_v1";

  function getSelectedPledgeText() {
    if (!choicesWrap) return "";
    const checked = choicesWrap.querySelector('input[name="hkPledgeOption"]:checked');
    return checked ? checked.value : "";
  }

  function loadStoredPledge() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return null;
      return JSON.parse(raw);
    } catch (_err) {
      return null;
    }
  }

  function saveStoredPledge() {
    const nameVal = (nameInput ? nameInput.value : "").trim();
    const pledgeVal = getSelectedPledgeText();
    const payload = {
      name: nameVal,
      pledge: pledgeVal,
      date: formatIndonesianDate(new Date())
    };
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
      if (savedNote) {
        savedNote.textContent = "Tersimpan otomatis di peramban perangkat ini.";
      }
    } catch (_err) {
      // Abaikan jika penyimpanan lokal dibatasi
    }
    return payload;
  }

  function drawPledgeCertificate() {
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const rawName = (nameInput ? nameInput.value : "").trim();
    const displayName = rawName || "Sahabat Rimba Indonesia";
    const pledgeText =
      getSelectedPledgeText() ||
      "Tidak membuka lahan dengan membakar serta tidak membuang bara api di area vegetasi kering.";
    const dateStr = formatIndonesianDate(new Date());

    // Buat nomor seri deterministik dari nama
    let hash = 2026;
    for (let i = 0; i < displayName.length; i++) {
      hash = (hash * 31 + displayName.charCodeAt(i)) % 9000 + 1000;
    }

    drawWhiteCertificateBase(ctx, width, height, {
      topPillText: "HUTANKITA INDONESIA  •  GERAKAN PELESTARIAN RIMBA NUSANTARA",
      mainTitle: "SERTIFIKAT & BADGE IKRAR",
      subTitle: "KOMITMEN AKSI NYATA PELESTARIAN HUTAN HUJAN TROPIS INDONESIA",
      dateStr,
      serialId: `No. Registrasi: HK-IKRAR-2026-${hash}`,
      badgeTopText: "PENJAGA RIMBA",
      badgeCenterMain: "VERIFIED",
      badgeCenterSub: "HUTANKITA"
    });

    const centerX = width / 2;
    ctx.save();
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    // Pengantar nama penerima
    ctx.font = "400 21px 'Outfit', sans-serif";
    ctx.fillStyle = "#334155";
    ctx.fillText("Sertifikat kehormatan ini diberikan dengan bangga kepada:", centerX, 294);

    // Nama lengkap penerima
    ctx.font = "800 48px 'Outfit', sans-serif";
    ctx.fillStyle = "#064e3b";
    const trimmedName = displayName.length > 34 ? displayName.slice(0, 34) + "..." : displayName;
    ctx.fillText(trimmedName, centerX, 354);

    // Garis aksen di bawah nama penerima
    const nameW = Math.min(680, Math.max(320, ctx.measureText(trimmedName).width + 60));
    ctx.strokeStyle = "#b48a3e";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(centerX - nameW / 2, 392);
    ctx.lineTo(centerX + nameW / 2, 392);
    ctx.stroke();

    // Label ikrar
    ctx.font = "500 20px 'Outfit', sans-serif";
    ctx.fillStyle = "#334155";
    ctx.fillText(
      "Atas kesungguhan mengikrarkan komitmen nyata sebagai Penjaga Hutan Tropis Nusantara:",
      centerX,
      436
    );

    // Kotak kutipan ikrar berlatar hijau gading lembut
    const boxW = 1040;
    const boxH = 170;
    const boxX = centerX - boxW / 2;
    const boxY = 472;

    ctx.fillStyle = "#f0fdf4";
    ctx.strokeStyle = "rgba(16, 185, 129, 0.38)";
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(boxX, boxY, boxW, boxH, 14) : ctx.rect(boxX, boxY, boxW, boxH);
    ctx.fill();
    ctx.stroke();

    // Pita aksen vertikal kiri & kanan pada kotak ikrar
    ctx.fillStyle = "#059669";
    ctx.fillRect(boxX, boxY + 16, 6, boxH - 32);
    ctx.fillRect(boxX + boxW - 6, boxY + 16, 6, boxH - 32);

    ctx.font = "600 26px 'Outfit', sans-serif";
    ctx.fillStyle = "#052e16";
    const quotedPledge = `"${pledgeText}"`;
    const lines = wrapCanvasLines(ctx, quotedPledge, boxW - 110).slice(0, 3);
    const lineHeight = 38;
    const startY = boxY + boxH / 2 - ((lines.length - 1) * lineHeight) / 2;
    lines.forEach((line, idx) => {
      ctx.fillText(line, centerX, startY + idx * lineHeight);
    });

    ctx.restore();
  }

  const stored = loadStoredPledge();
  if (stored) {
    if (nameInput && stored.name) {
      nameInput.value = stored.name;
    }
    if (choicesWrap && stored.pledge) {
      const radios = choicesWrap.querySelectorAll('input[name="hkPledgeOption"]');
      radios.forEach((r) => {
        if (r.value === stored.pledge) {
          r.checked = true;
        }
      });
    }
  }

  ensureFounderSignatureLoaded(() => {
    drawPledgeCertificate();
  });
  drawPledgeCertificate();

  if (nameInput) {
    nameInput.addEventListener("input", () => {
      saveStoredPledge();
      drawPledgeCertificate();
      // Sinkronkan juga ke input nama sertifikat kuis bila kosong
      const quizNameInput = document.getElementById("hkQuizCertName");
      if (quizNameInput && !quizNameInput.value.trim()) {
        quizNameInput.value = nameInput.value;
      }
    });
  }

  if (choicesWrap) {
    choicesWrap.addEventListener("change", () => {
      saveStoredPledge();
      drawPledgeCertificate();
    });
  }

  function openPledgeDialog() {
    drawPledgeCertificate();
    if (typeof dialog.showModal === "function") {
      if (!dialog.open) dialog.showModal();
    } else {
      dialog.setAttribute("open", "");
    }
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(drawPledgeCertificate);
    }
    if (nameInput) {
      setTimeout(() => nameInput.focus(), 60);
    }
  }

  function closePledgeDialog() {
    if (typeof dialog.close === "function" && dialog.open) {
      dialog.close();
    } else {
      dialog.removeAttribute("open");
    }
  }

  btnPledge.addEventListener("click", () => {
    saveStoredPledge();
    openPledgeDialog();
  });

  if (closeBtn) closeBtn.addEventListener("click", closePledgeDialog);
  if (closeTopBtn) closeTopBtn.addEventListener("click", closePledgeDialog);

  dialog.addEventListener("click", (event) => {
    const rect = dialog.getBoundingClientRect();
    const clickedInDialog =
      rect.top <= event.clientY &&
      event.clientY <= rect.top + rect.height &&
      rect.left <= event.clientX &&
      event.clientX <= rect.left + rect.width;
    if (!clickedInDialog) {
      closePledgeDialog();
    }
  });

  if (downloadBtn) {
    downloadBtn.addEventListener("click", () => {
      saveStoredPledge();
      drawPledgeCertificate();
      try {
        const dataUrl = canvas.toDataURL("image/png");
        const link = document.createElement("a");
        const cleanName = ((nameInput ? nameInput.value : "").trim() || "sahabat-rimba")
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/^-|-$/g, "");
        link.download = `sertifikat-ikrar-hutankita-${cleanName || "indonesia"}.png`;
        link.href = dataUrl;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        if (typeof window.showToast === "function") {
          window.showToast("Sertifikat & Badge Ikrar (PNG) berhasil diunduh.");
        }
      } catch (_err) {
        if (typeof window.showToast === "function") {
          window.showToast("Gagal mengunduh sertifikat pada peramban ini.");
        }
      }
    });
  }
}

